import { evaluateOrderGifts } from './gift-rules';
import { Product } from '../entities/product.entity';

function mockProduct(overrides: Partial<Product> = {}): Product {
  return {
    id: 1,
    sku: 'SP-001',
    name: 'Sản phẩm A',
    category: 'general',
    retailPrice: 100000,
    wholesalePrice: 90000,
    stock: 20,
    unit: 'hop',
    unitTypes: [
      {
        type: 'hop',
        label: 'Hộp',
        retailPrice: 100000,
        wholesalePrice: 90000,
        minWholesaleQty: 2,
        qtyPerUnit: 1,
        giftRules: [
          {
            id: 'gift-coc',
            label: 'Tặng cốc',
            trigger: { scope: 'line', minQty: 3 },
            gift: { name: 'Cốc in logo', qty: 1, qtyMultiplier: 'once' },
          },
        ],
      },
    ],
    isActive: true,
    createdAt: new Date(),
    updatedAt: new Date(),
    ...overrides,
  } as Product;
}

describe('evaluateOrderGifts', () => {
  it('không tặng khi chưa đủ SL', () => {
    const gifts = evaluateOrderGifts(
      [{ productId: 1, unitType: 'hop', quantity: 2 }],
      new Map([[1, mockProduct()]]),
    );
    expect(gifts).toHaveLength(0);
  });

  it('tặng quà khi đủ minQty theo dòng', () => {
    const gifts = evaluateOrderGifts(
      [{ productId: 1, unitType: 'hop', quantity: 3 }],
      new Map([[1, mockProduct()]]),
    );
    expect(gifts).toHaveLength(1);
    expect(gifts[0]?.name).toBe('Cốc in logo');
    expect(gifts[0]?.qty).toBe(1);
  });

  it('scope product — cộng SL các dòng cùng SP', () => {
    const product = mockProduct({
      unitTypes: [
        {
          type: 'hop',
          label: 'Hộp',
          retailPrice: 100000,
          wholesalePrice: null,
          minWholesaleQty: 0,
          qtyPerUnit: 1,
          giftRules: [
            {
              id: 'gift-bundle',
              label: 'Tặng túi',
              trigger: { scope: 'product', minQty: 5 },
              gift: { name: 'Túi vải', qty: 1 },
            },
          ],
        },
        {
          type: 'thung',
          label: 'Thùng',
          retailPrice: 400000,
          wholesalePrice: null,
          minWholesaleQty: 0,
          qtyPerUnit: 1,
          giftRules: [
            {
              id: 'gift-bundle',
              label: 'Tặng túi',
              trigger: { scope: 'product', minQty: 5 },
              gift: { name: 'Túi vải', qty: 1 },
              applyPer: 'order',
            },
          ],
        },
      ],
    });
    const gifts = evaluateOrderGifts(
      [
        { productId: 1, unitType: 'hop', quantity: 2 },
        { productId: 1, unitType: 'thung', quantity: 3 },
      ],
      new Map([[1, product]]),
    );
    expect(gifts).toHaveLength(1);
    expect(gifts[0]?.name).toBe('Túi vải');
  });
});

src/common/gift-rules.ts.content:
import type {
  OrderGiftSnapshot,
  ProductGiftRule,
  ProductUnitType,
} from './product-types';
import type { Product } from '../entities/product.entity';
import {
  effectiveQuantityForCondition,
  matchesQuantityCondition,
  resolveUnit,
} from './product-units';

export type CheckoutLineContext = {
  productId: number;
  unitType: string;
  quantity: number;
};

function giftQtyForRule(rule: ProductGiftRule, effectiveQty: number): number {
  const base = Math.max(1, Math.floor(rule.gift.qty || 1));
  const minQty = Math.max(1, Math.floor(rule.trigger.minQty ?? 1));
  const multiplier = rule.gift.qtyMultiplier ?? 'once';

  if (multiplier === 'once') return base;

  if (multiplier === 'per_step') {
    const step = Math.max(1, Math.floor(rule.trigger.stepQty ?? minQty));
    const times = Math.floor(effectiveQty / step);
    return base * Math.max(0, times);
  }

  const times = Math.floor(effectiveQty / minQty);
  return base * Math.max(0, times);
}

function collectRulesFromUnit(unit: ProductUnitType): ProductGiftRule[] {
  return (unit.giftRules ?? []).filter((r) => r?.id && r.gift?.name?.trim());
}

function buildGiftSnapshot(
  rule: ProductGiftRule,
  ctx: CheckoutLineContext,
  qty: number,
): OrderGiftSnapshot {
  return {
    ruleId: rule.id,
    label: rule.label,
    sku: rule.gift.sku,
    name: rule.gift.name,
    qty,
    image: rule.gift.image,
    productId: rule.gift.productId ?? ctx.productId,
    unitType: ctx.unitType,
  };
}

/**
 * Đánh giá quà tặng theo dòng đã gộp và catalog.
 * Rule `scope: product` dùng tổng SL (sell_unit) các dòng cùng productId.
 */
export function evaluateOrderGifts(
  mergedLines: CheckoutLineContext[],
  productsById: Map<number, Product>,
): OrderGiftSnapshot[] {
  const productSellTotals = new Map<number, number>();
  for (const line of mergedLines) {
    const prev = productSellTotals.get(line.productId) ?? 0;
    productSellTotals.set(line.productId, prev + line.quantity);
  }

  const gifts: OrderGiftSnapshot[] = [];
  const orderRuleApplied = new Set<string>();

  for (const line of mergedLines) {
    const product = productsById.get(line.productId);
    if (!product) continue;
    const unit = resolveUnit(product, line.unitType);
    const rules = collectRulesFromUnit(unit);

    for (const rule of rules) {
      const scope = rule.trigger.scope ?? 'line';
      const sellQty =
        scope === 'product'
          ? (productSellTotals.get(line.productId) ?? line.quantity)
          : line.quantity;
      const effectiveQty = effectiveQuantityForCondition(
        sellQty,
        unit,
        rule.trigger,
      );

      if (!matchesQuantityCondition(effectiveQty, rule.trigger)) continue;

      const applyPer =
        rule.applyPer ?? (scope === 'product' ? 'order' : 'line');
      const dedupeKey =
        scope === 'product'
          ? `product:${rule.id}:${line.productId}`
          : applyPer === 'order'
            ? `order:${rule.id}:${line.productId}:${line.unitType}`
            : `line:${rule.id}:${line.productId}:${line.unitType}`;
      if (
        (applyPer === 'order' || scope === 'product') &&
        orderRuleApplied.has(dedupeKey)
      ) {
        continue;
      }

      const qty = giftQtyForRule(rule, effectiveQty);
      if (qty <= 0) continue;

      gifts.push(buildGiftSnapshot(rule, line, qty));
      if (applyPer === 'order' || scope === 'product') {
        orderRuleApplied.add(dedupeKey);
      }
    }
  }

  return gifts;
}

src/common/image-processor.ts.content:
import sharp from 'sharp';

export interface ImageProcessOptions {
  maxWidth?: number;
  quality?: number;
}

const DEFAULT_MAX_WIDTH = 1920;
const DEFAULT_QUALITY = 80;

export function isImageMime(mime: string): boolean {
  return mime.startsWith('image/') && !mime.includes('svg');
}

export function isImageExt(ext: string): boolean {
  return [
    '.jpg',
    '.jpeg',
    '.png',
    '.gif',
    '.webp',
    '.bmp',
    '.tif',
    '.tiff',
    '.heic',
    '.heif',
  ].includes(ext.toLowerCase());
}

export async function processImageBuffer(
  buffer: Buffer,
  options?: ImageProcessOptions,
): Promise<{
  webpBuffer: Buffer;
  originalFormat: string;
  width: number;
  height: number;
}> {
  const maxWidth = options?.maxWidth ?? DEFAULT_MAX_WIDTH;
  const quality = options?.quality ?? DEFAULT_QUALITY;

  let image = sharp(buffer);
  const metadata = await image.metadata();
  const originalFormat = metadata.format ?? 'jpeg';
  let width = metadata.width ?? 0;
  let height = metadata.height ?? 0;

  if (width > maxWidth) {
    const ratio = maxWidth / width;
    width = maxWidth;
    height = Math.round(height * ratio);
    image = image.resize(maxWidth, undefined, {
      fit: 'inside',
      withoutEnlargement: true,
    });
  }

  const webpBuffer = await image.webp({ quality }).toBuffer();
  return { webpBuffer, originalFormat, width, height };
}

src/common/legacy-audit-timestamps.ts.content:
/** Bản ghi legacy có created_at / updated_at nullable. */
export type LegacyAuditEntity = {
  createdAt?: Date | null;
  updatedAt?: Date | null;
};

export function touchLegacyAuditTimestamps(
  entity: LegacyAuditEntity,
  isCreate = false,
): void {
  const now = new Date();
  if (isCreate || !entity.createdAt) {
    entity.createdAt = entity.createdAt ?? now;
  }
  entity.updatedAt = now;
}

export function backfillLegacyAuditTimestampsIfMissing(
  entity: LegacyAuditEntity,
): boolean {
  const now = new Date();
  let changed = false;
  if (!entity.createdAt) {
    entity.createdAt = now;
    changed = true;
  }
  if (!entity.updatedAt) {
    entity.updatedAt = entity.createdAt ?? now;
    changed = true;
  }
  return changed;
}

