/**
 * Helper pagination dùng chung cho list API.
 */

/** Giới hạn `limit` mặc định cho danh sách admin (phân trang UI). */
export const ADMIN_TABLE_MAX_LIMIT = 100;

/** Giới hạn khi client tải toàn bộ để xuất Excel / hiển thị đầy đủ. */
export const ADMIN_TABLE_EXPORT_MAX_LIMIT = 5000;

export interface PaginationParams {
  page: number;
  limit: number;
  skip: number;
}

/**
 * Chuẩn hóa page, limit và tính skip.
 * @param page - trang (>= 1)
 * @param limit - số bản ghi/trang (1..maxLimit)
 * @param maxLimit - giới hạn tối đa (mặc định 100)
 */
export function normalizePageLimit(
  page: number,
  limit: number,
  maxLimit: number = ADMIN_TABLE_MAX_LIMIT,
): PaginationParams {
  const p = Math.max(1, page);
  const l = Math.min(maxLimit, Math.max(1, limit));
  return {
    page: p,
    limit: l,
    skip: (p - 1) * l,
  };
}

export interface PaginationMeta {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
}

/**
 * Tạo object pagination cho response.
 */
export function paginationMeta(
  page: number,
  limit: number,
  total: number,
): PaginationMeta {
  return {
    page,
    limit,
    total,
    totalPages: Math.ceil(total / limit) || 1,
  };
}

/** Phân trang khi client yêu cầu tải đủ bản ghi (xuất Excel, xem tất cả). */
export function normalizeExportPageLimit(
  page: number,
  limit: number,
): PaginationParams {
  return normalizePageLimit(page, limit, ADMIN_TABLE_EXPORT_MAX_LIMIT);
}

src/common/parse-column-filters.ts.content:
/** Trích `filter[columnId]` từ query string admin list. */
export function parseColumnFiltersFromQuery(
  query?: Record<string, string | undefined>,
): Record<string, string> | undefined {
  if (!query) return undefined;

  const filters: Record<string, string> = {};
  for (const [key, value] of Object.entries(query)) {
    const match = key.match(/^filter\[(.+)\]$/);
    if (match && value?.trim()) {
      filters[match[1]] = value.trim();
    }
  }

  return Object.keys(filters).length ? filters : undefined;
}

src/common/parse-list-query.ts.content:
import {
  ADMIN_TABLE_EXPORT_MAX_LIMIT,
  normalizePageLimit,
  type PaginationParams,
} from './pagination';

/** Chuẩn hóa `limit` query admin — cho phép tải tới `ADMIN_TABLE_EXPORT_MAX_LIMIT`. */
export function parseAdminListLimit(raw: unknown, defaultLimit = 20): number {
  const parsed = Number.parseInt(String(raw ?? ''), 10);
  if (!Number.isFinite(parsed)) return defaultLimit;
  return Math.min(ADMIN_TABLE_EXPORT_MAX_LIMIT, Math.max(1, parsed));
}

export function parseAdminListPage(raw: unknown, defaultPage = 1): number {
  const parsed = Number.parseInt(String(raw ?? ''), 10);
  if (!Number.isFinite(parsed)) return defaultPage;
  return Math.max(1, parsed);
}

export function parseAdminListPagination(
  pageRaw: unknown,
  limitRaw: unknown,
  defaultLimit = 20,
): PaginationParams {
  return normalizePageLimit(
    parseAdminListPage(pageRaw),
    parseAdminListLimit(limitRaw, defaultLimit),
    ADMIN_TABLE_EXPORT_MAX_LIMIT,
  );
}

src/common/parse-setting-value.ts.content:
/** Giá trị settings từ DB có thể bị JSON double-encode (MikroORM type:json). */
export function parseSettingValue(raw: unknown, fallback: string): string {
  if (raw === '') return '';
  if (raw == null) return fallback;

  if (typeof raw === 'string') {
    try {
      const parsed = JSON.parse(raw);
      return typeof parsed === 'string' ? parsed : raw;
    } catch {
      return raw;
    }
  }

  if (typeof raw === 'number' || typeof raw === 'boolean') {
    return String(raw);
  }

  return fallback;
}

